    if (typeof value !== 'string' || value.length === 0) throw new Error(`Invalid schedule file: missing ${fieldName}`);

    return value;
}

function requireTimestamp(value, fieldName) {
    const timestamp = requireString(value, fieldName);
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Invalid schedule file: invalid ${fieldName}`);

    return timestamp;
}

function requireBoolean(value, fieldName) {
    if (typeof value !== 'boolean') throw new Error(`Invalid schedule file: ${fieldName} must be a boolean`);

    return value;
}

function requireNonNegativeInteger(value, fieldName) {
    if (!Number.isInteger(value) || value < 0) {
        throw new Error(`Invalid schedule file: ${fieldName} must be a non-negative integer`);
    }

    return value;
}

function requireNullableString(value, fieldName) {
    if (value === null) return null;

    return requireString(value, fieldName);
}

function parseOptionalString(schedule, fieldName) {
    if (schedule[fieldName] === undefined) return {};
    if (typeof schedule[fieldName] !== 'string') throw new Error(`Invalid schedule file: ${fieldName} must be a string`);

    return { [fieldName]: schedule[fieldName] };
}

function parseOptionalNullableString(schedule, fieldName) {
    if (schedule[fieldName] === undefined) return {};

    return { [fieldName]: requireNullableString(schedule[fieldName], fieldName) };
}

function parseOptionalConversationId(schedule) {
    if (schedule.conversationId === undefined) return {};

    return { conversationId: requireNullableString(schedule.conversationId, 'conversationId') };
}

function parseContext(value) {
    const context = requireObject(value, 'context');
    const kind = requireString(context.kind, 'context.kind');
    if (!ACTION_CONTEXT_KINDS.has(kind)) throw new Error(`Invalid schedule file: unsupported context kind ${kind}`);
